From f77313f30686c7629f03da1fb506a346a9ae23b0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:30:51 +0100
Subject: [PATCH] plugins/fadingpopups: Cancel animations when screen is
 locked/unlocked

Windows below the lock screen aren't painted, so a popup that was still
fading out when the screen got locked stayed frozen and finished fading
only after unlocking. Cancel the animations like slidingpopups does.

BUG: 518425
---
 .../fadingpopups/package/contents/code/main.js      | 13 +++++++++++++
 1 file changed, 13 insertions(+)

diff --git a/src/plugins/fadingpopups/package/contents/code/main.js b/src/plugins/fadingpopups/package/contents/code/main.js
index 34c55b477e..a6b8ca94a1 100644
--- a/src/plugins/fadingpopups/package/contents/code/main.js
+++ b/src/plugins/fadingpopups/package/contents/code/main.js
@@ -103,6 +103,18 @@ var fadingPopupsEffect = {
             }
         }
     },
+    stopAnimations: function () {
+        for (const window of effects.stackingOrder) {
+            if (window.fadeInAnimation) {
+                cancel(window.fadeInAnimation);
+                delete window.fadeInAnimation;
+            }
+            if (window.fadeOutAnimation) {
+                cancel(window.fadeOutAnimation);
+                delete window.fadeOutAnimation;
+            }
+        }
+    },
     init: function () {
         fadingPopupsEffect.loadConfig();

@@ -110,6 +122,7 @@ var fadingPopupsEffect = {
         effects.windowAdded.connect(fadingPopupsEffect.slotWindowAdded);
         effects.windowClosed.connect(fadingPopupsEffect.slotWindowClosed);
         effects.windowDataChanged.connect(fadingPopupsEffect.slotWindowDataChanged);
+        effects.screenLockingChanged.connect(fadingPopupsEffect.stopAnimations);
     }
 };

